CREATE FUNCTION "udfbuildiso8601date"(p_year integer, p_month integer, p_day integer) RETURNS timestamp(3) without time zone LANGUAGE plpgsql IMMUTABLE AS $body$
BEGIN
  RETURN CAST(CAST(p_year AS TEXT) || '-' || UDFTWODIGITZEROFILL(p_month) || '-' || UDFTWODIGITZEROFILL(p_day) || 'T00:00:00' AS TIMESTAMP);
END $body$;

CREATE FUNCTION "udfminimumdate"(p_x timestamp(3) without time zone, p_y timestamp(3) without time zone) RETURNS timestamp(3) without time zone LANGUAGE plpgsql IMMUTABLE AS $body$
DECLARE
  v_z timestamp(3) without time zone;
BEGIN
  IF p_x <= p_y THEN
    v_z := p_x;
  ELSE
    v_z := p_y;
  END IF;
  RETURN v_z;
END $body$;

CREATE FUNCTION "udftwodigitzerofill"(p_number integer) RETURNS character(2) LANGUAGE plpgsql IMMUTABLE AS $body$
DECLARE
  v_result character(2);
BEGIN
  IF p_number > 9 THEN
    v_result := CAST(p_number AS VARCHAR(2));
  ELSE
    v_result := CAST('0' || CAST(p_number AS TEXT) AS VARCHAR(2));
  END IF;
  RETURN v_result;
END $body$;
